describe("private coding adapter with only its native child boundary replaced", () => {
  let actions: string[];
  let acknowledgments: unknown[];
  let wrongCorrelation: boolean;
  let mutate: (value: ReturnType<typeof envelope>) => void;
  beforeEach(() => {
    actions = [];
    acknowledgments = [];
    wrongCorrelation = false;
    mutate = () => undefined;
    external.spawn.mockReset();
    external.spawn.mockImplementation((_command, args) => {
      const argv = args as readonly string[];
      const stdout = new PassThrough();
      const stderr = new PassThrough();
      const events = new EventEmitter();
      let document: unknown;
      let pending = "";
      const close = (code = 0) => queueMicrotask(() => events.emit("close", code));
      const emit = (value: unknown) => stdout.write(`${JSON.stringify(value)}\n`);
      const action = argv.at(-1) ?? "";
      const stdin = new Writable({
        write(chunk, _encoding, done) {
          pending += String(chunk);
          let newline = pending.indexOf("\n");
          while (newline >= 0) {
            const frame: unknown = JSON.parse(pending.slice(0, newline));
            pending = pending.slice(newline + 1);
            if (document === undefined) {
              document = frame;
              actions.push(action);
              queueMicrotask(() => {
                if (action === "readiness") {
                  emit({
                    available: true,
                    reason: "Synthetic child transport only",
                    versions: { codex: "synthetic" },
                  });
                  close();
                } else if (action === "preflight") {
                  emit(qualification());
                  close();
                } else if (action === "run")
                  emit({
                    kind: "authorize",
                    correlationId: wrongCorrelation ? randomUUID() : request.correlationId,
                    sequence: 1,
                  });
                else {
                  const value = envelope();
                  mutate(value);
                  emit(value);
                  close();
                }
              });
            } else {
              acknowledgments.push(frame);
              const value = envelope();
              mutate(value);
              emit(value);
              close();
            }
            newline = pending.indexOf("\n");
          }
          done();
        },
      });
      const child = Object.assign(events, {
        stdin,
        stdout,
        stderr,
        kill: () => {
          close(1);
          return true;
        },
      });
      if (argv.includes("/usr/bin/wslpath"))
        queueMicrotask(() => {
          stdout.write("/synthetic-workspace\n");
          close();
        });
      return child as unknown as ReturnType<typeof import("node:child_process").spawn>;
    });
  });
  it("T-AC-787 native bridge resolves an absolute trusted executable without ambient vendor environment", async () => {
    await createCodingProvider(config, { platform: "win32" });
    for (const [command, args, options] of external.spawn.mock.calls) {
      expect(isAbsolute(command)).toBe(true);
      expect(JSON.stringify(args)).not.toContain(config.bindings[0]?.broker.apiKey);
      const environment = (options as { env?: NodeJS.ProcessEnv } | undefined)?.env ?? {};
      expect(Object.hasOwn(environment, "GODSEYE_CODEX_API_KEY")).toBe(false);
      expect(Object.hasOwn(environment, "GODSEYE_CLAUDE_CODE_API_KEY")).toBe(false);
    }
  });
  it("T-AC-789 acknowledges exact native authorization only after the current controller fence", async () => {
    const provider = await createCodingProvider(config, { platform: "win32" });
    let fences = 0;
    const observed = await provider.submit(request, {
      signal: new AbortController().signal,
      assertActive: async () => {
        fences++;
      },
    });
    expect(fences).toBe(2);
    expect(acknowledgments).toEqual([
      { kind: "authorized", correlationId: request.correlationId, sequence: 1 },
    ]);
    expect(actions.filter((action) => action === "run")).toHaveLength(1);
    expect(observed).toMatchObject({
      state: "succeeded",
      stopped: true,
      result: {
        taskId: request.taskId,
        worktreeId: request.worktreeId,
        usage: { accounting: "reserved-conservatively", costMicros: null },
      },
    });
  });
  it("T-AC-789 refuses a mismatched native correlation without acknowledging or retrying", async () => {
    wrongCorrelation = true;
    const provider = await createCodingProvider(config, { platform: "win32" });
    const observed = await provider.submit(request, {
      signal: new AbortController().signal,
      assertActive: async () => undefined,
    });
    expect(observed.state).toBe("unknown");
    expect(acknowledgments).toEqual([]);
    expect(actions.filter((action) => action === "run")).toHaveLength(1);
  });
  it("T-AC-789 revocation at per-request authorization sends no ACK and retains uncertainty", async () => {
    const provider = await createCodingProvider(config, { platform: "win32" });
    let fences = 0;
    const observed = await provider.submit(request, {
      signal: new AbortController().signal,
      assertActive: async () => {
        if (++fences === 2) throw new Error("Synthetic revoked controller grant");
      },
    });
    expect(observed).toMatchObject({ state: "unknown", stopped: false, workspace: "quarantined" });
    expect(acknowledgments).toEqual([]);
  });
  it("T-AC-788 inspection never executes, renews authorization or restarts a child task", async () => {
    const provider = await createCodingProvider(config, { platform: "win32" });
    await provider.inspect(request, new AbortController().signal);
    expect(actions).toEqual(["readiness", "inspect"]);
    expect(acknowledgments).toEqual([]);
  });
  it("T-AC-790 missing exact guest candidate tree evidence never becomes an accepted result", async () => {
    mutate = (value) => {
      Reflect.deleteProperty(value.guestResult, "treeHash");
    };
    const provider = await createCodingProvider(config, { platform: "win32" });
    const observed = await provider.submit(request, {
      signal: new AbortController().signal,
      assertActive: async () => undefined,
    });
    expect(observed.state).toBe("unknown");
    expect(observed.result).toBeUndefined();
  });
  it("T-AC-790 untrusted guest artifact digest never becomes an accepted result", async () => {
    mutate = (value) => {
      value.guestResult.patchSha256 = "0".repeat(64);
    };
    const provider = await createCodingProvider(config, { platform: "win32" });
    const observed = await provider.submit(request, {
      signal: new AbortController().signal,
      assertActive: async () => undefined,
    });
    expect(observed.state).toBe("unknown");
    expect(observed.result).toBeUndefined();
  });
});
